  Button MakeButton(string text,Action action){var b=new Button{Content=text,Margin=new Thickness(0,0,8,0)};b.Click+=delegate{Safe(action);};AutomationProperties.SetName(b,text);return b;}
  void Safe(Action action){try{action();}catch(Exception e){status.Text=e.Message;}}
  void LoadCatalog(bool force){var timing=Stopwatch.StartNew();System.Threading.Tasks.Task.Factory.StartNew(()=>{var cached=service.CachedApplications();return Tuple.Create(cached,service.ApplicationEntries(cached,service.Launchpad()));}).ContinueWith(task=>Dispatcher.BeginInvoke((Action)delegate{
    if(task.IsFaulted){status.Text="앱 목록 확인 실패: "+task.Exception.GetBaseException().Message;return;}catalog=task.Result.Item1;entries=task.Result.Item2;BuildCategories();RefreshGrid();UiPerformance.Record(service.Root,"launchpad-catalog-bind",timing.Elapsed.TotalMilliseconds);
    DateTimeOffset refreshed;if(force||!DateTimeOffset.TryParse(catalog.Refreshed,out refreshed)||DateTimeOffset.Now-refreshed>TimeSpan.FromHours(24))Rescan();
   }));}
  void Rescan(){if(requestBusy)return;requestBusy=true;status.Text="설치된 앱을 찾는 중…";service.DiscoverApplicationsAsync().ContinueWith(task=>{
   ApplicationEntry[] all=null;Exception error=task.IsFaulted?task.Exception.GetBaseException():null;try{if(error==null)all=service.ApplicationEntries(task.Result,service.Launchpad());}catch(Exception e){error=e;}
   Dispatcher.BeginInvoke((Action)delegate{requestBusy=false;if(error!=null){status.Text="앱 검색 실패: "+error.Message;return;}catalog=task.Result;entries=all;RefreshGrid();status.Text=catalog.Apps.Count+"개 설치 항목 · "+(catalog.Warnings.Count>0?String.Join(" ",catalog.Warnings):"목록 갱신 완료");});});}
  void BuildCategories(){categories.Children.Clear();foreach(var c in config.Categories){var current=c;var b=MakeButton(c.Name,()=>{category=current.Id;folder=null;search.Clear();pageIndex=0;selected=0;Mutate(cfg=>cfg.SelectedCategory=category);BuildCategories();RefreshGrid();});b.BorderBrush=c.Id==category?UxTheme.Accent:Brushes.Transparent;b.FontWeight=c.Id==category?FontWeights.SemiBold:FontWeights.Normal;b.AllowDrop=c.Id!="all";b.DragOver+=delegate(object s,DragEventArgs e){e.Effects=e.Data.GetDataPresent("GUNT.App")?DragDropEffects.Move:DragDropEffects.None;e.Handled=true;};b.Drop+=delegate(object s,DragEventArgs e){var id=e.Data.GetData("GUNT.App") as string;if(id!=null)Safe(()=>MoveApp(id,current.Id,null));e.Handled=true;};categories.Children.Add(b);}}
  int Columns {get{return Math.Max(3,Math.Min(config.Columns,(int)((Width-40)/112)));}}
  int Rows {get{return Math.Max(1,Math.Min(4,(int)((Height-226)/(config.IconSize+55))));}}
  int Capacity {get{return Columns*Rows;}}
  void RefreshGrid(){if(config==null)return;int token=++generation;visible=DesktopService.FilterApplications(entries,config,category,folder,search.Text);var folders=String.IsNullOrWhiteSpace(search.Text)&&folder==null&&category!="favorites"?config.Folders.Where(x=>category=="all"||x.Category==category).Select(x=>new ApplicationEntry{Id=x.Id,Name=x.Name,Kind="group",Target=x.Id,Category=x.Category,Context="앱 폴더"}).ToArray():String.IsNullOrWhiteSpace(search.Text)?new ApplicationEntry[0]:config.Folders.Where(x=>DesktopService.MatchCommand(search.Text,x.Name)>0).Select(x=>new ApplicationEntry{Id=x.Id,Name=x.Name,Kind="group",Target=x.Id,Category=x.Category,Context="앱 폴더"}).ToArray();
   var display=folders.Concat(visible).ToArray();int pages=Math.Max(1,(display.Length+Capacity-1)/Capacity);pageIndex=Math.Max(0,Math.Min(pageIndex,pages-1));var items=display.Skip(pageIndex*Capacity).Take(Capacity).ToArray();selected=Math.Max(0,Math.Min(selected,items.Length-1));grid.Children.Clear();buttons.Clear();grid.Columns=Columns;grid.Rows=Rows;
   foreach(var app in items){var item=DesktopService.Item(config,app.Id);var b=new Button{Tag=app,Margin=new Thickness(4),Padding=new Thickness(6,8,6,6),BorderBrush=Brushes.Transparent,Background=Brushes.Transparent,HorizontalContentAlignment=HorizontalAlignment.Stretch,VerticalContentAlignment=VerticalAlignment.Center,AllowDrop=true,ToolTip=(item.Label??app.Name)+"\n"+app.Context};
    var stack=new StackPanel{VerticalAlignment=VerticalAlignment.Center};var image=new Image{Width=config.IconSize,Height=config.IconSize,Stretch=Stretch.Uniform};stack.Children.Add(image);b.MouseEnter+=delegate{IconHover(image);};stack.Children.Add(new TextBlock{Text=(item.Favorite?"★ ":"")+(item.Label??app.Name),FontSize=12,TextAlignment=TextAlignment.Center,TextTrimming=TextTrimming.CharacterEllipsis,Margin=new Thickness(0,8,0,0)});if(app.Kind=="project"||app.Kind=="session"||app.Kind=="command"||!String.IsNullOrWhiteSpace(search.Text))stack.Children.Add(new TextBlock{Text=app.Context,FontSize=11,Foreground=UxTheme.Muted,TextAlignment=TextAlignment.Center,TextTrimming=TextTrimming.CharacterEllipsis});b.Content=stack;
    AutomationProperties.SetName(b,(item.Label??app.Name)+" · "+app.Context);AutomationProperties.SetAutomationId(b,app.Id);
    string pose=item.Pose??(app.Kind=="group"?"folder":config.Categories.Where(x=>x.Id==(item.Category??app.Category)).Select(x=>x.Pose).FirstOrDefault());
    icons.Get(app,pose,config.IconTheme=="mascot").ContinueWith(task=>{if(task.Status==System.Threading.Tasks.TaskStatus.RanToCompletion)Dispatcher.BeginInvoke((Action)delegate{if(token==generation)image.Source=task.Result;});});
    b.PreviewMouseLeftButtonDown+=delegate(object s,MouseButtonEventArgs e){dragSource=app;down=e.GetPosition(this);dragged=false;selected=buttons.IndexOf(b);MarkSelection();};
    b.PreviewMouseMove+=delegate(object s,MouseEventArgs e){if(e.LeftButton!=MouseButtonState.Pressed||dragSource!=app||app.Kind=="group")return;Point now=e.GetPosition(this);if(Math.Abs(now.X-down.X)<SystemParameters.MinimumHorizontalDragDistance&&Math.Abs(now.Y-down.Y)<SystemParameters.MinimumVerticalDragDistance)return;dragged=true;modal=true;try{DragDrop.DoDragDrop(b,new DataObject("GUNT.App",app.Id),DragDropEffects.Move);}finally{modal=false;dragSource=null;}};
    b.Click+=delegate{if(!dragged)Safe(()=>ActivateApp(app));dragged=false;};b.DragOver+=delegate(object s,DragEventArgs e){if(e.Data.GetDataPresent("GUNT.App")){e.Effects=DragDropEffects.Move;b.BorderBrush=UxTheme.Accent;b.BorderThickness=new Thickness(3,1,1,1);e.Handled=true;}};b.DragLeave+=delegate{b.BorderThickness=new Thickness(1);MarkSelection();};
    b.Drop+=delegate(object s,DragEventArgs e){string id=e.Data.GetData("GUNT.App") as string;if(id!=null)Safe(()=>{if(app.Kind=="group")MoveApp(id,app.Category,app.Id);else Reorder(id,app.Id);});e.Handled=true;};b.ContextMenu=AppMenu(app);grid.Children.Add(b);buttons.Add(b);
   }
   back.Visibility=folder!=null?Visibility.Visible:Visibility.Collapsed;breadcrumb.Text=folder!=null?"Launchpad / "+config.Folders.First(x=>x.Id==folder).Name:String.IsNullOrWhiteSpace(search.Text)?config.Categories.First(x=>x.Id==category).Name:"검색 결과";previous.IsEnabled=pageIndex>0;next.IsEnabled=pageIndex<pages-1;pageLabel.Text=(pageIndex+1)+" / "+pages;pagingVisibility(pages>1);status.Text=display.Length==0?"일치하는 항목이 없습니다. 검색어나 카테고리를 바꿔 보세요.":display.Length+"개 항목";MarkSelection();
  }
  void pagingVisibility(bool show){previous.Visibility=next.Visibility=pageLabel.Visibility=show?Visibility.Visible:Visibility.Collapsed;}
  void MarkSelection(){for(int i=0;i<buttons.Count;i++){buttons[i].BorderBrush=i==selected?UxTheme.Accent:Brushes.Transparent;buttons[i].Background=i==selected?UxTheme.Surface:Brushes.Transparent;}}
  void Mutate(Action<LaunchpadConfig> change){var fresh=service.Launchpad();change(fresh);service.SaveLaunchpad(fresh);config=fresh;}
  void MoveApp(string id,string to,string into){Mutate(c=>{var item=DesktopService.Item(c,id);if(to=="favorites")item.Favorite=true;else{item.Category=to;item.Folder=into;}});BuildCategories();RefreshGrid();}
  void Reorder(string source,string target){if(source==target)return;var order=visible.Select(x=>x.Id).ToList();order.Remove(source);int position=order.IndexOf(target);order.Insert(Math.Max(0,position),source);Mutate(c=>{var destination=DesktopService.Item(c,target);var item=DesktopService.Item(c,source);if(category=="favorites")item.Favorite=true;else{item.Folder=destination.Folder;item.Category=destination.Category??entries.First(x=>x.Id==target).Category;}for(int i=0;i<order.Count;i++)if(category=="favorites")DesktopService.Item(c,order[i]).FavoriteOrder=i;else DesktopService.Item(c,order[i]).Order=i;});RefreshGrid();}
  void OnKeys(object sender,KeyEventArgs e){if(modal)return;if(e.Key==Key.Escape){e.Handled=true;if(!String.IsNullOrEmpty(search.Text))search.Clear();else if(folder!=null){folder=null;RefreshGrid();}else Dismiss();return;}if(e.Key==Key.Enter){e.Handled=true;if(buttons.Count>0)Safe(()=>ActivateApp((ApplicationEntry)buttons[selected].Tag));return;}
   if(new[]{Key.Left,Key.Right,Key.Up,Key.Down}.Contains(e.Key)&&buttons.Count>0){e.Handled=true;int delta=e.Key==Key.Left?-1:e.Key==Key.Right?1:e.Key==Key.Up?-Columns:Columns;int index=selected+delta;if(index<0&&pageIndex>0){pageIndex--;selected=Capacity-1;RefreshGrid();}else if(index>=buttons.Count&&next.IsEnabled){pageIndex++;selected=0;RefreshGrid();}else{selected=Math.Max(0,Math.Min(index,buttons.Count-1));MarkSelection();}buttons[selected].Focus();return;}
   if(e.Key==Key.PageDown&&next.IsEnabled){pageIndex++;selected=0;RefreshGrid();e.Handled=true;}else if(e.Key==Key.PageUp&&previous.IsEnabled){pageIndex--;selected=0;RefreshGrid();e.Handled=true;}
   else if(!search.IsKeyboardFocusWithin&&Keyboard.Modifiers==ModifierKeys.None&&((e.Key>=Key.A&&e.Key<=Key.Z)||(e.Key>=Key.D0&&e.Key<=Key.D9)))search.Focus();
  }
  void ActivateApp(ApplicationEntry app){if(requestBusy)return;if(app.Kind=="group"){folder=app.Id;search.Clear();pageIndex=0;selected=0;RefreshGrid();search.Focus();return;}if(app.Kind=="session"){PreviewSession(app);return;}
   requestBusy=true;status.Text=app.Name+" 실행 요청 중…";System.Threading.Tasks.Task.Factory.StartNew(()=>service.LaunchApplication(app)).ContinueWith(task=>Dispatcher.BeginInvoke((Action)delegate{requestBusy=false;if(task.IsFaulted){status.Text=task.Exception.GetBaseException().Message;return;}Safe(()=>Mutate(c=>DesktopService.Item(c,app.Id).LastLaunched=DateTimeOffset.Now.ToString("o")));status.Text=task.Result;if(config.CloseAfterLaunch)Dismiss();}));
  }
  public void Toggle(){if(modal||requestBusy)return;if(IsVisible&&IsActive)Dismiss();else Present();}
  public void Present(){var watch=Stopwatch.StartNew();Safe(()=>{config=service.Launchpad();category=config.SelectedCategory;folder=null;pageIndex=0;search.Clear();BuildCategories();Place();RefreshGrid();});Show();Topmost=true;Activate();Topmost=false;search.Focus();OpeningMotion();Dispatcher.BeginInvoke(DispatcherPriority.Render,(Action)delegate{UiPerformance.Record(service.Root,"launchpad-warm-open",watch.Elapsed.TotalMilliseconds);});}
  void Dismiss(){if(modal||requestBusy)return;BeginAnimation(OpacityProperty,null);Hide();hiddenSince=DateTime.UtcNow;}
  [DllImport("user32.dll")]static extern IntPtr GetForegroundWindow();
  [DllImport("user32.dll")]static extern bool SetWindowPos(IntPtr h,IntPtr after,int x,int y,int width,int height,uint flags);
  void Place(){var screen=config.Monitor=="foreground"?System.Windows.Forms.Screen.FromHandle(GetForegroundWindow()):System.Windows.Forms.Screen.FromPoint(System.Windows.Forms.Cursor.Position);double scale=GuntLayout.Scale(screen);var area=screen.WorkingArea;Width=Math.Min(940,area.Width/scale-24);Height=Math.Min(590,area.Height/scale-24);if(nativeSource!=null)SetWindowPos(new WindowInteropHelper(this).Handle,IntPtr.Zero,area.Left+(area.Width-(int)(Width*scale))/2,area.Top+(area.Height-(int)(Height*scale))/2,(int)(Width*scale),(int)(Height*scale),0x14);}
  IntPtr Hook(IntPtr h,int message,IntPtr w,IntPtr l,ref bool handled){if(message==0x8006){if(w.ToInt32()==1)Present();else Toggle();handled=true;}return IntPtr.Zero;}
